			/**
			 * 저장
			 */
			function doSave(type){
			        
			    var msg = "";
			    var rowData = app.lookup("grdList").getSelectedRow();

			    // 매칭 해제인 경우는 값을 비우고, 아닌 경우 현재 로그인 담당자의 정보와 AEB130에 등록된 수급자관리번호를 저장한다. 
			    if(type == "DELETE"){
			        app.lookup("dmSave").setValue("RECIPI_MNG_NO", "");
			        app.lookup("dmSave").setValue("MTCHNG_PIC_ENFSN_NO", "");
			        app.lookup("dmSave").setValue("MTCHNG_PIC_INST_NO", "");
			        app.lookup("dmSave").setValue("MTCHNG_PIC_TELNO", "");
			        app.lookup("dmSave").setValue("MTCHNG_YMD", "");
			        msg = "수급자관리번호를 매칭해제하시겠습니까?";
			    }else{
			        app.lookup("dmSave").setValue("MTCHNG_PIC_ENFSN_NO", util.Auth.getUserInfo(app, "ENFSN_NO"));
			        app.lookup("dmSave").setValue("MTCHNG_PIC_INST_NO", util.Auth.getUserInfo(app, "INST_NO"));
			        app.lookup("dmSave").setValue("MTCHNG_PIC_TELNO", util.Auth.getUserInfo(app, "WRD_TELNO"));
			        // 오늘일자(YYYYMMDD)를 매칭일자로 지정한다.
			        app.lookup("dmSave").setValue("MTCHNG_YMD", moment().subtract(0, "months").format("YYYYMMDD"));
			        msg = "수급자관리번호를 매칭하시겠습니까?";
			    }
			    
			    console.log("가기 전의 dmSave ::: ", app.lookup("dmSave").getDatas());
			    
			    util.Msg.confirm(app, msg, null, function(){
			        //조회 서브미션 호출
			        util.Submit.send(app, "subSave", function(pbSuccess){
			            if(pbSuccess) {
			                // 조회 목록 재처리
			                doList();
			            }   
			        }); 
			        /*확인버튼 콜백*/
			    }, function(){
			         /*취소버튼 콜백*/            
			    }, "알림", null, true);
			    
			}

